p = Path('core/pipeline.py');
text = p.read_text(encoding='utf-8');
if 'tool_runtime_failed_terminal' in text:
  print('already hardened');
else:
  # insert terminal after tool_runtime block (conservative string marker)
  marker = 'tool_runtime_done = True'
  insert = '''
            # Harden Phase 1: tool_runtime failure is terminal under tool-first
            # (no generate fallback that previously hung 984s after max_steps)
            if tool_runtime_enabled() and not tool_runtime_done:
                result.degraded.append("tool_runtime_failed_terminal")
                return self._fail(
                    result, "tool_runtime", "tool_runtime_failed_terminal", time.perf_counter(), attempts,
                )
'''
  if marker in text:
    text = text.replace(marker, marker + insert, 1)
    p.write_text(text, encoding='utf-8')
    print('HARDENED terminal marker inserted')
  else:
    print('WARN: marker not found, skip insert')
